using System.Diagnostics.Metrics;
using System.Globalization;
using System.Text.Json;
using Hispania.Platform.Contracts.Events;
using Microsoft.Data.Sqlite;

namespace Hispania.Platform.Persistence.Sqlite;

/// <summary>Single-process/single-dispatcher SQLite V1 store. Event and initial delivery rows commit together.</summary>
public sealed class SqliteDurablePlatformEventBus : IDurablePlatformEventBusV1, IDisposable
{
    private readonly string connectionString;
    private readonly DurableEventOptionsV1 options;
    private readonly SemaphoreSlim dispatchLock = new(1, 1);
    private readonly Meter meter = new("Hispania.Platform.DurableEvents");
    private Counter<long> Published = null!;
    private Counter<long> Delivered = null!;
    private Counter<long> Retrying = null!;
    private Counter<long> Failed = null!;
    private Counter<long> DeadLettered = null!;
    public SqliteDurablePlatformEventBus(string path, DurableEventOptionsV1? options = null)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(path))!);
        connectionString = new SqliteConnectionStringBuilder { DataSource = path, Mode = SqliteOpenMode.ReadWriteCreate, Cache = SqliteCacheMode.Shared, Pooling = false }.ToString();
        this.options = options ?? new();
        if (this.options.MaximumPayloadBytes < 1 || this.options.MaximumAttempts < 1 || this.options.EffectiveRetryDelay < TimeSpan.Zero || this.options.EffectiveProcessingLease <= TimeSpan.Zero) throw new ArgumentOutOfRangeException(nameof(options));
        Published = meter.CreateCounter<long>("events.published"); Delivered = meter.CreateCounter<long>("events.delivered"); Retrying = meter.CreateCounter<long>("events.retrying"); Failed = meter.CreateCounter<long>("events.failed"); DeadLettered = meter.CreateCounter<long>("events.dead_lettered");
        meter.CreateObservableGauge("events.pending", () => CountStatus(DurableDeliveryStatus.Pending));
        using var db = Open(); using var cmd = db.CreateCommand();
        cmd.CommandText = """
            PRAGMA journal_mode=WAL;
            CREATE TABLE IF NOT EXISTS Events(EventId TEXT PRIMARY KEY, EventType TEXT NOT NULL, Version INTEGER NOT NULL, OccurredAt TEXT NOT NULL, CorrelationId TEXT NULL, CausationId TEXT NULL, Producer TEXT NOT NULL, PayloadJson TEXT NOT NULL);
            CREATE TABLE IF NOT EXISTS Subscribers(SubscriberId TEXT PRIMARY KEY);
            CREATE TABLE IF NOT EXISTS Deliveries(DeliveryId TEXT PRIMARY KEY, EventId TEXT NOT NULL REFERENCES Events(EventId), SubscriberId TEXT NOT NULL REFERENCES Subscribers(SubscriberId), Status INTEGER NOT NULL, AttemptCount INTEGER NOT NULL, NextAttemptAt TEXT NOT NULL, LastError TEXT NULL, DeliveredAt TEXT NULL, DeadLetteredAt TEXT NULL, UNIQUE(EventId, SubscriberId));
            CREATE TABLE IF NOT EXISTS DeliveryAttempts(AttemptId TEXT PRIMARY KEY, DeliveryId TEXT NOT NULL REFERENCES Deliveries(DeliveryId), AttemptNumber INTEGER NOT NULL, FinishedAt TEXT NOT NULL, Outcome INTEGER NOT NULL, Error TEXT NULL);
            CREATE INDEX IF NOT EXISTS IX_Deliveries_Ready ON Deliveries(Status, NextAttemptAt);
            """; cmd.ExecuteNonQuery();
    }
    private SqliteConnection Open() { var db = new SqliteConnection(connectionString); db.Open(); return db; }
    private long CountStatus(DurableDeliveryStatus status) { try { using var db = Open(); using var cmd = db.CreateCommand(); cmd.CommandText = "SELECT COUNT(*) FROM Deliveries WHERE Status=$status"; cmd.Parameters.AddWithValue("$status", (int)status); return (long)(cmd.ExecuteScalar() ?? 0L); } catch { return 0; } }
    public async ValueTask<Guid> PublishAsync<TEvent>(TEvent value, string producer, IReadOnlyCollection<string> subscribers, EventContext? context = null, string? causationId = null, CancellationToken cancellationToken = default) where TEvent : IPlatformEvent
    {
        ArgumentNullException.ThrowIfNull(value); ArgumentException.ThrowIfNullOrWhiteSpace(producer);
        if (string.IsNullOrWhiteSpace(value.EventType) || value.EventType.Length > 200 || value.Version < 1) throw new ArgumentException("Invalid stable event identity.");
        var json = JsonSerializer.Serialize(value);
        if (System.Text.Encoding.UTF8.GetByteCount(json) > options.MaximumPayloadBytes) throw new InvalidDataException("Durable event payload exceeds the configured size limit.");
        if (subscribers.Any(x => string.IsNullOrWhiteSpace(x) || x.Length > 200) || subscribers.Distinct(StringComparer.Ordinal).Count() != subscribers.Count) throw new ArgumentException("Subscriber IDs must be stable, non-empty, unique identifiers.");
        var eventId = Guid.NewGuid(); var now = DateTimeOffset.UtcNow;
        await using var db = Open(); await using var tx = await db.BeginTransactionAsync(cancellationToken).ConfigureAwait(false);
        foreach (var subscriber in subscribers)
        {
            await using var sub = db.CreateCommand(); sub.Transaction = (SqliteTransaction)tx; sub.CommandText = "INSERT INTO Subscribers(SubscriberId) VALUES($id) ON CONFLICT DO NOTHING"; sub.Parameters.AddWithValue("$id", subscriber); await sub.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);
        }
        await using (var cmd = db.CreateCommand())
        {
            cmd.Transaction = (SqliteTransaction)tx; cmd.CommandText = "INSERT INTO Events VALUES($id,$type,$version,$occurred,$corr,$cause,$producer,$payload)";
            cmd.Parameters.AddWithValue("$id", eventId.ToString("D")); cmd.Parameters.AddWithValue("$type", value.EventType); cmd.Parameters.AddWithValue("$version", value.Version); cmd.Parameters.AddWithValue("$occurred", now.ToString("O")); cmd.Parameters.AddWithValue("$corr", (object?)context?.CorrelationId ?? DBNull.Value); cmd.Parameters.AddWithValue("$cause", (object?)causationId ?? DBNull.Value); cmd.Parameters.AddWithValue("$producer", producer); cmd.Parameters.AddWithValue("$payload", json); await cmd.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);
        }
        foreach (var subscriber in subscribers)
        {
            await using var cmd = db.CreateCommand(); cmd.Transaction = (SqliteTransaction)tx; cmd.CommandText = "INSERT INTO Deliveries VALUES($delivery,$event,$subscriber,$status,0,$next,NULL,NULL,NULL)"; cmd.Parameters.AddWithValue("$delivery", Guid.NewGuid().ToString("D")); cmd.Parameters.AddWithValue("$event", eventId.ToString("D")); cmd.Parameters.AddWithValue("$subscriber", subscriber); cmd.Parameters.AddWithValue("$status", (int)DurableDeliveryStatus.Pending); cmd.Parameters.AddWithValue("$next", now.ToString("O")); await cmd.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);
        }
        await tx.CommitAsync(cancellationToken).ConfigureAwait(false); Published.Add(1, new KeyValuePair<string, object?>("event.type", value.EventType)); return eventId;
    }
    public async ValueTask<int> DispatchOnceAsync(CancellationToken cancellationToken = default)
    {
        if (!await dispatchLock.WaitAsync(0, cancellationToken).ConfigureAwait(false)) return 0;
        try
        {
            var now = DateTimeOffset.UtcNow; await using var db = Open();
            await using var recover = db.CreateCommand(); recover.CommandText = "UPDATE Deliveries SET Status=$pending, NextAttemptAt=$now WHERE Status=$processing AND NextAttemptAt <= $now"; recover.Parameters.AddWithValue("$pending", (int)DurableDeliveryStatus.Pending); recover.Parameters.AddWithValue("$processing", (int)DurableDeliveryStatus.Processing); recover.Parameters.AddWithValue("$now", now.ToString("O")); await recover.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);
            await using var query = db.CreateCommand(); query.CommandText = "SELECT d.DeliveryId,d.EventId,d.SubscriberId,d.AttemptCount,e.EventType,e.Version,e.OccurredAt,e.CorrelationId,e.CausationId,e.Producer,e.PayloadJson FROM Deliveries d JOIN Events e USING(EventId) WHERE d.Status=$status AND d.NextAttemptAt <= $now ORDER BY d.NextAttemptAt LIMIT 100"; query.Parameters.AddWithValue("$status", (int)DurableDeliveryStatus.Pending); query.Parameters.AddWithValue("$now", now.ToString("O"));
            var list = new List<(Guid delivery, Guid eventId, string subscriber, int attempts, PlatformEventEnvelopeV1 envelope)>(); await using (var reader = await query.ExecuteReaderAsync(cancellationToken).ConfigureAwait(false)) while (await reader.ReadAsync(cancellationToken).ConfigureAwait(false)) list.Add((Guid.Parse(reader.GetString(0)), Guid.Parse(reader.GetString(1)), reader.GetString(2), reader.GetInt32(3), new(Guid.Parse(reader.GetString(1)), reader.GetString(4), reader.GetInt32(5), DateTimeOffset.Parse(reader.GetString(6), CultureInfo.InvariantCulture), reader.IsDBNull(7) ? null : reader.GetString(7), reader.IsDBNull(8) ? null : reader.GetString(8), reader.GetString(9), reader.GetString(10))));
            var completed = 0;
            foreach (var item in list)
            {
                cancellationToken.ThrowIfCancellationRequested();
                await using var claim = db.CreateCommand(); claim.CommandText = "UPDATE Deliveries SET Status=$processing,AttemptCount=AttemptCount+1,NextAttemptAt=$lease WHERE DeliveryId=$id AND Status=$pending"; claim.Parameters.AddWithValue("$processing", (int)DurableDeliveryStatus.Processing); claim.Parameters.AddWithValue("$pending", (int)DurableDeliveryStatus.Pending); claim.Parameters.AddWithValue("$lease", now.Add(options.EffectiveProcessingLease).ToString("O")); claim.Parameters.AddWithValue("$id", item.delivery.ToString("D")); if (await claim.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false) == 0) continue;
                try { await DeliverAsync(item.envelope, item.subscriber, cancellationToken).ConfigureAwait(false); await SetTerminalAsync(item.delivery, DurableDeliveryStatus.Delivered, item.attempts + 1, null, cancellationToken).ConfigureAwait(false); Delivered.Add(1); }
                catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested) { throw; }
                catch (Exception ex) { var dead = item.attempts + 1 >= options.MaximumAttempts; var err = ex.GetType().Name + ": subscriber failed"; await SetFailureAsync(item.delivery, dead, item.attempts + 1, err, cancellationToken).ConfigureAwait(false); Failed.Add(1); if (dead) DeadLettered.Add(1); else Retrying.Add(1); }
                completed++;
            }
            return completed;
        }
        finally { dispatchLock.Release(); }
    }
    /// <remarks>Server composition provides the fixed, explicit codec/handler registry.</remarks>
    public Func<PlatformEventEnvelopeV1, string, CancellationToken, ValueTask>? DeliveryHandler { get; set; }
    private ValueTask DeliverAsync(PlatformEventEnvelopeV1 envelope, string subscriber, CancellationToken token) => DeliveryHandler is null ? ValueTask.FromException(new InvalidOperationException("Durable event handler registry is not configured.")) : DeliveryHandler(envelope, subscriber, token);
    private async ValueTask SetTerminalAsync(Guid id, DurableDeliveryStatus status, int attempt, string? error, CancellationToken ct) { await using var db = Open(); await using var tx = await db.BeginTransactionAsync(ct).ConfigureAwait(false); var now = DateTimeOffset.UtcNow; await using (var history = db.CreateCommand()) { history.Transaction = (SqliteTransaction)tx; history.CommandText = "INSERT INTO DeliveryAttempts VALUES($attempt,$delivery,$number,$time,$outcome,$error)"; history.Parameters.AddWithValue("$attempt", Guid.NewGuid().ToString("D")); history.Parameters.AddWithValue("$delivery", id.ToString("D")); history.Parameters.AddWithValue("$number", attempt); history.Parameters.AddWithValue("$time", now.ToString("O")); history.Parameters.AddWithValue("$outcome", (int)status); history.Parameters.AddWithValue("$error", (object?)error ?? DBNull.Value); await history.ExecuteNonQueryAsync(ct).ConfigureAwait(false); } await using (var cmd = db.CreateCommand()) { cmd.Transaction = (SqliteTransaction)tx; cmd.CommandText = "UPDATE Deliveries SET Status=$status,LastError=$error,DeliveredAt=$delivered,DeadLetteredAt=$dead WHERE DeliveryId=$id"; cmd.Parameters.AddWithValue("$status", (int)status); cmd.Parameters.AddWithValue("$error", (object?)error ?? DBNull.Value); cmd.Parameters.AddWithValue("$delivered", status == DurableDeliveryStatus.Delivered ? now.ToString("O") : DBNull.Value); cmd.Parameters.AddWithValue("$dead", status == DurableDeliveryStatus.DeadLettered ? now.ToString("O") : DBNull.Value); cmd.Parameters.AddWithValue("$id", id.ToString("D")); await cmd.ExecuteNonQueryAsync(ct).ConfigureAwait(false); } await tx.CommitAsync(ct).ConfigureAwait(false); }
    private async ValueTask SetFailureAsync(Guid id, bool dead, int attempt, string error, CancellationToken ct) { await using var db = Open(); await using var tx = await db.BeginTransactionAsync(ct).ConfigureAwait(false); var now = DateTimeOffset.UtcNow; var status = dead ? DurableDeliveryStatus.DeadLettered : DurableDeliveryStatus.Pending; await using (var history = db.CreateCommand()) { history.Transaction = (SqliteTransaction)tx; history.CommandText = "INSERT INTO DeliveryAttempts VALUES($attempt,$delivery,$number,$time,$outcome,$error)"; history.Parameters.AddWithValue("$attempt", Guid.NewGuid().ToString("D")); history.Parameters.AddWithValue("$delivery", id.ToString("D")); history.Parameters.AddWithValue("$number", attempt); history.Parameters.AddWithValue("$time", now.ToString("O")); history.Parameters.AddWithValue("$outcome", (int)status); history.Parameters.AddWithValue("$error", error); await history.ExecuteNonQueryAsync(ct).ConfigureAwait(false); } await using (var cmd = db.CreateCommand()) { cmd.Transaction = (SqliteTransaction)tx; cmd.CommandText = "UPDATE Deliveries SET Status=$status,NextAttemptAt=$next,LastError=$error,DeadLetteredAt=$dead WHERE DeliveryId=$id"; cmd.Parameters.AddWithValue("$status", (int)status); var seconds = Math.Min(options.EffectiveRetryDelay.TotalSeconds * Math.Pow(2, Math.Clamp(attempt - 1, 0, 20)), 900); cmd.Parameters.AddWithValue("$next", now.AddSeconds(seconds).ToString("O")); cmd.Parameters.AddWithValue("$error", error); cmd.Parameters.AddWithValue("$dead", dead ? now.ToString("O") : DBNull.Value); cmd.Parameters.AddWithValue("$id", id.ToString("D")); await cmd.ExecuteNonQueryAsync(ct).ConfigureAwait(false); } await tx.CommitAsync(ct).ConfigureAwait(false); }
    public async ValueTask<IReadOnlyList<DurableDeliveryViewV1>> ListDeliveriesAsync(DurableDeliveryStatus? status = null, int limit = 100, CancellationToken cancellationToken = default) { await using var db = Open(); await using var cmd = db.CreateCommand(); cmd.CommandText = "SELECT d.DeliveryId,d.EventId,e.EventType,d.SubscriberId,d.Status,d.AttemptCount,d.NextAttemptAt,d.LastError,d.DeliveredAt,d.DeadLetteredAt FROM Deliveries d JOIN Events e USING(EventId) WHERE ($status IS NULL OR d.Status=$status) ORDER BY d.NextAttemptAt LIMIT $limit"; cmd.Parameters.AddWithValue("$status", status is null ? DBNull.Value : (object)(int)status.Value); cmd.Parameters.AddWithValue("$limit", Math.Clamp(limit,1,500)); var result = new List<DurableDeliveryViewV1>(); await using var reader = await cmd.ExecuteReaderAsync(cancellationToken).ConfigureAwait(false); while (await reader.ReadAsync(cancellationToken).ConfigureAwait(false)) result.Add(new(Guid.Parse(reader.GetString(0)), Guid.Parse(reader.GetString(1)), reader.GetString(2), reader.GetString(3), (DurableDeliveryStatus)reader.GetInt32(4), reader.GetInt32(5), DateTimeOffset.Parse(reader.GetString(6), CultureInfo.InvariantCulture), reader.IsDBNull(7)?null:reader.GetString(7), reader.IsDBNull(8)?null:DateTimeOffset.Parse(reader.GetString(8), CultureInfo.InvariantCulture), reader.IsDBNull(9)?null:DateTimeOffset.Parse(reader.GetString(9), CultureInfo.InvariantCulture))); return result; }
    public async ValueTask<DurableEventDetailV1?> GetEventAsync(Guid eventId, CancellationToken cancellationToken = default) { await using var db=Open(); await using var cmd=db.CreateCommand(); cmd.CommandText="SELECT EventType,Version,OccurredAt,CorrelationId,CausationId,Producer,PayloadJson FROM Events WHERE EventId=$id"; cmd.Parameters.AddWithValue("$id",eventId.ToString("D")); await using var r=await cmd.ExecuteReaderAsync(cancellationToken); if(!await r.ReadAsync(cancellationToken)) return null; var e=new PlatformEventEnvelopeV1(eventId,r.GetString(0),r.GetInt32(1),DateTimeOffset.Parse(r.GetString(2), CultureInfo.InvariantCulture),r.IsDBNull(3)?null:r.GetString(3),r.IsDBNull(4)?null:r.GetString(4),r.GetString(5),r.GetString(6)); await r.DisposeAsync(); return new(e, await GetDeliveriesForEventAsync(db,eventId,cancellationToken)); }
    private static async ValueTask<IReadOnlyList<DurableDeliveryV1>> GetDeliveriesForEventAsync(SqliteConnection db, Guid id, CancellationToken ct) { await using var c=db.CreateCommand(); c.CommandText="SELECT DeliveryId,SubscriberId,Status,AttemptCount,NextAttemptAt,LastError,DeliveredAt,DeadLetteredAt FROM Deliveries WHERE EventId=$id"; c.Parameters.AddWithValue("$id",id.ToString("D")); var a=new List<DurableDeliveryV1>(); await using var r=await c.ExecuteReaderAsync(ct); while(await r.ReadAsync(ct)) a.Add(new(Guid.Parse(r.GetString(0)),id,r.GetString(1),(DurableDeliveryStatus)r.GetInt32(2),r.GetInt32(3),DateTimeOffset.Parse(r.GetString(4), CultureInfo.InvariantCulture),r.IsDBNull(5)?null:r.GetString(5),r.IsDBNull(6)?null:DateTimeOffset.Parse(r.GetString(6), CultureInfo.InvariantCulture),r.IsDBNull(7)?null:DateTimeOffset.Parse(r.GetString(7), CultureInfo.InvariantCulture))); return a; }
    public async ValueTask<bool> ReplayDeadLetterAsync(Guid deliveryId, CancellationToken cancellationToken = default) { await using var db=Open(); await using var cmd=db.CreateCommand(); cmd.CommandText="UPDATE Deliveries SET Status=$pending,AttemptCount=0,NextAttemptAt=$now,LastError=NULL,DeadLetteredAt=NULL,DeliveredAt=NULL WHERE DeliveryId=$id AND Status=$dead"; cmd.Parameters.AddWithValue("$pending",(int)DurableDeliveryStatus.Pending); cmd.Parameters.AddWithValue("$dead",(int)DurableDeliveryStatus.DeadLettered); cmd.Parameters.AddWithValue("$now",DateTimeOffset.UtcNow.ToString("O")); cmd.Parameters.AddWithValue("$id",deliveryId.ToString("D")); return await cmd.ExecuteNonQueryAsync(cancellationToken)>0; }
    public async ValueTask<IReadOnlySet<string>> GetKnownSubscribersAsync(CancellationToken cancellationToken = default) { await using var db=Open(); await using var c=db.CreateCommand(); c.CommandText="SELECT SubscriberId FROM Subscribers ORDER BY SubscriberId"; var s=new HashSet<string>(StringComparer.Ordinal); await using var r=await c.ExecuteReaderAsync(cancellationToken); while(await r.ReadAsync(cancellationToken))s.Add(r.GetString(0)); return s; }
    public async ValueTask<IReadOnlyList<DurableDeliveryAttemptV1>> GetDeliveryAttemptsAsync(Guid deliveryId, CancellationToken cancellationToken = default) { await using var db=Open(); await using var cmd=db.CreateCommand(); cmd.CommandText="SELECT AttemptId,AttemptNumber,FinishedAt,Outcome,Error FROM DeliveryAttempts WHERE DeliveryId=$id ORDER BY AttemptNumber,FinishedAt"; cmd.Parameters.AddWithValue("$id",deliveryId.ToString("D")); var rows=new List<DurableDeliveryAttemptV1>(); await using var r=await cmd.ExecuteReaderAsync(cancellationToken); while(await r.ReadAsync(cancellationToken)) rows.Add(new(Guid.Parse(r.GetString(0)),deliveryId,r.GetInt32(1),DateTimeOffset.Parse(r.GetString(2),CultureInfo.InvariantCulture),(DurableDeliveryStatus)r.GetInt32(3),r.IsDBNull(4)?null:r.GetString(4))); return rows; }
    public async ValueTask<DurableEventHealthV1> GetHealthAsync(CancellationToken cancellationToken = default) { await using var db=Open(); await using var cmd=db.CreateCommand(); cmd.CommandText="SELECT Status,COUNT(*) FROM Deliveries GROUP BY Status"; long pending=0,processing=0,delivered=0,dead=0; await using var r=await cmd.ExecuteReaderAsync(cancellationToken); while(await r.ReadAsync(cancellationToken)) switch((DurableDeliveryStatus)r.GetInt32(0)) { case DurableDeliveryStatus.Pending: pending=r.GetInt64(1); break; case DurableDeliveryStatus.Processing: processing=r.GetInt64(1); break; case DurableDeliveryStatus.Delivered: delivered=r.GetInt64(1); break; case DurableDeliveryStatus.DeadLettered: dead=r.GetInt64(1); break; } return new(pending,processing,delivered,dead,true); }
    public void Dispose() { dispatchLock.Dispose(); meter.Dispose(); }
}